import { useEffect, useState } from 'react';

/**
 * A hook that provides a responsive scaling factor based on the current screen width
 * relative to a reference width (default 1920px)
 */
export const useResponsiveScale = (referenceWidth = 1920) => {
  const [scale, setScale] = useState(1);
  const [viewportDimensions, setViewportDimensions] = useState({
    width: window.innerWidth,
    height: window.innerHeight
  });

  useEffect(() => {
    const handleResize = () => {
      const windowWidth = window.innerWidth;
      const windowHeight = window.innerHeight;
      
      // If window width is less than reference width, scale down proportionally
      // Otherwise, keep scale at 1 (100%)
      const newScale = windowWidth < referenceWidth 
        ? Math.max(windowWidth / referenceWidth, 0.3) // Limit minimum scale to 0.3 (30%)
        : 1;
      
      setScale(newScale);
      setViewportDimensions({
        width: windowWidth,
        height: windowHeight
      });
    };

    // Initialize scale on mount
    handleResize();
    
    // Add event listener for window resize
    window.addEventListener('resize', handleResize);
    
    // Clean up event listener on unmount
    return () => window.removeEventListener('resize', handleResize);
  }, [referenceWidth]);

  return { scale, viewportDimensions };
};

/**
 * ResponsiveScaling component that applies a scale transform to its children
 * based on the current screen width relative to a reference width (default 1920px)
 */
const ResponsiveScaling = ({ children, referenceWidth = 1920 }) => {
  const { scale, viewportDimensions } = useResponsiveScale(referenceWidth);
  
  // Style for the outer container that manages overflow and scrolling
  const containerStyle = {
    width: '100vw',
    height: '100vh',
    overflow: 'auto',
    position: 'fixed',
    top: 0,
    left: 0
  };
  
  // Style for the scaled content
  const contentStyle = {
    transform: `scale(${scale})`,
    transformOrigin: 'center top',
    width: `${referenceWidth}px`,
    minHeight: '100vh',
    position: 'relative',
    margin: '0 auto'
  };
  
  return (
    <div style={containerStyle} className="responsive-scaling-container">
      <div style={contentStyle} className="responsive-scaling-content">
        {children}
      </div>
    </div>
  );
};

export default ResponsiveScaling;
